CREATE TABLE b (grp text, amount int);
INSERT INTO a VALUES ('x', 10), ('x', 5), ('y', 20), ('z', 7);
INSERT INTO b VALUES ('x', 15), ('y', 18), ('w', 3);

SELECT COALESCE(a.grp, b.grp) AS grp,
       COALESCE(a.total, 0) AS a_total,
       COALESCE(b.total, 0) AS b_total,
       COALESCE(a.total, 0) - COALESCE(b.total, 0) AS diff
FROM (SELECT grp, SUM(amount) AS total FROM a GROUP BY grp) a
FULL OUTER JOIN (SELECT grp, SUM(amount) AS total FROM b GROUP BY grp) b ON b.grp = a.grp
ORDER BY grp;

