source = {'USD': 5000, 'EUR': 3000, 'GBP': 800, 'JPY': 120000}
target = {'USD': 5000, 'EUR': 3030, 'GBP': 300, 'JPY': 120000}
tolerance = {'USD': 0, 'EUR': 50, 'GBP': 10, 'JPY': 0}

failed = False
for cur in sorted(source):
    diff = target[cur] - source[cur]
    if diff == 0:
        print(f"{cur} match")
    elif abs(diff) <= tolerance[cur]:
        print(f"{cur} within tolerance {diff:+}")
    else:
        failed = True
        print(f"{cur} FAIL {diff:+}")
print('overall FAIL' if failed else 'overall OK')

