CREATE TABLE ledger (day date, amount numeric(12,2));
CREATE TABLE wh (day date, amount numeric(12,2));
INSERT INTO ledger VALUES ('2026-01-05', 10.00), ('2026-01-05', 20.00), ('2026-01-06', 5.00), ('2026-01-07', 8.00);
INSERT INTO wh VALUES ('2026-01-05', 30.03), ('2026-01-06', 4.00);

WITH d AS (
  SELECT COALESCE(s.day, t.day) AS day,
         COALESCE(s.total, 0) - COALESCE(t.total, 0) AS diff
  FROM (SELECT day, SUM(amount) AS total FROM ledger GROUP BY day) s
  FULL OUTER JOIN (SELECT day, SUM(amount) AS total FROM wh GROUP BY day) t ON t.day = s.day
)
SELECT day, diff, CASE WHEN abs(diff) <= 0.05 THEN 'ok' ELSE 'check' END AS status
FROM d
WHERE abs(diff) > 0.05
ORDER BY day;
